// formatMessage builds a failure message from the variadic msgAndArgs.
// With no args, returns defaultMsg. With one arg, uses it as a literal
// message. With multiple args and a string format, applies fmt.Sprintf
// so callers can write: test.AssertEqual(t, got, want, "case %s", name).
func formatMessage(defaultMsg string, msgAndArgs []any) string {
	if len(msgAndArgs) == 0 {
		return defaultMsg
	}
	if len(msgAndArgs) == 1 {
		return fmt.Sprintf("%v", msgAndArgs[0])
	}
	if format, _isOk := msgAndArgs[0].(string); _isOk {
		return fmt.Sprintf(format, msgAndArgs[1:]...)
	}
	return fmt.Sprintf("%v", msgAndArgs[0])
}

// diffDetail renders a why-did-they-differ hint for the AssertEqual failure
// message. Returns "" when no sharper hint applies (caller falls back to the
// bare got/want rendering) — equal-length slices with a first differing
// element, maps, and structs all take this path today.
func diffDetail(got any, want any) string {
	gotType := fmt.Sprintf("%T", got)
	wantType := fmt.Sprintf("%T", want)
	if gotType != wantType {
		return fmt.Sprintf(" (type %v vs %v)", gotType, wantType)
	}
	if gs, _isOk := got.(string); _isOk {
		if ws, _isOk := want.(string); _isOk {
			if len(gs) == len(ws) {
				for i := range len(gs) {
					if gs[i] != ws[i] {
						return fmt.Sprintf(" (first differing byte at index %v, got %v)", i, fmt.Sprintf("%q", gs))
					}
				}
			}
			return fmt.Sprintf(" (length %v vs %v, got %v want %v)", len(gs), len(ws), fmt.Sprintf("%q", gs), fmt.Sprintf("%q", ws))
		}
	}
	gr := reflect.ValueOf(got)
	wr := reflect.ValueOf(want)
	if gr.Kind() == reflect.Slice || gr.Kind() == reflect.Array {
		if gr.Len() != wr.Len() {
			return fmt.Sprintf(" (length %v vs %v)", gr.Len(), wr.Len())
		}
		for i := range gr.Len() {
			if !reflect.DeepEqual(gr.Index(i).Interface(), wr.Index(i).Interface()) {
				return fmt.Sprintf(" (first differing element at index %v)", i)
			}
		}
	}
	return ""
}

// AssertEqual fails the test if got and want differ (via reflect.DeepEqual).
// The failure message names the first differing string byte / slice element,
// the length mismatch, or the type mismatch — the "why", not just the "that".
func AssertEqual(t testing.TB, got any, want any, msgAndArgs ...any) {
	t.Helper()
	if !reflect.DeepEqual(got, want) {
		msg := formatMessage("", msgAndArgs)
		detail := diffDetail(got, want)
		if msg != "" {
			t.Errorf("%s: expected %v, got %v%s", msg, want, got, detail)
		} else {
			t.Errorf("expected %v, got %v%s", want, got, detail)
		}
	}
}

