// isNil reports whether val is nil, including typed-nil pointers/slices/maps/
// chans/funcs/interfaces wrapped in `any`. Go's `val == nil` returns false for
// a `(*T)(nil)` stored in an interface because the interface carries the type
// tag; reflect.Value.IsNil checks the underlying value.
func isNil(val any) bool {
	if val == nil {
		return true
	}
	rv := reflect.ValueOf(val)
	kind := rv.Kind()
	if kind == reflect.Pointer || kind == reflect.Map || kind == reflect.Slice || kind == reflect.Chan || kind == reflect.Func || kind == reflect.Interface {
		return rv.IsNil()
	}
	return false
}

