// AssertContains fails the test if container does not contain item —
// substring for strings, element for slices/arrays, key for maps. The
// container/item pair must be shape-compatible: a non-string item against a
// string container, or an item whose type is not a valid map key, fails with
// an unsupported-combination message rather than silently passing.
// Example: test.AssertContains(t, output, "PASSED")
func AssertContains(t testing.TB, container any, item any, msgAndArgs ...any) {
	t.Helper()
	found := false
	applicable := true
	if s, _isOk := container.(string); _isOk {
		if needle, _isOk := item.(string); _isOk {
			found = kukistring.Contains(s, needle)
		} else {
			applicable = false
		}
	} else {
		rv := reflect.ValueOf(container)
		kind := rv.Kind()
		if kind == reflect.Slice || kind == reflect.Array {
			for i := range rv.Len() {
				if reflect.DeepEqual(rv.Index(i).Interface(), item) {
					found = true
					break
				}
			}
		} else if kind == reflect.Map {
			itemType := reflect.TypeOf(item)
			if itemType != nil && itemType.AssignableTo(rv.Type().Key()) {
				found = rv.MapIndex(reflect.ValueOf(item)).IsValid()
			} else {
				applicable = false
			}
		} else {
			applicable = false
		}
	}
	if !applicable {
		t.Errorf("unsupported container/item combination: container %T, item %T", container, item)
		return
	}
	if !found {
		t.Errorf("%s", formatMessage(fmt.Sprintf("expected %v to contain %v", container, item), msgAndArgs))
	}
}

